test("a refused staging is terminal, not retried", async () => {
  for (const outcome of ["suppressed_rejected", "invalid_source", "stale_source"]) {
    const { client } = fakeClient({ stage: { outcome } })
    assert.deepEqual(
      await run(client),
      { status: "unavailable", reason: "stage_rejected" },
      outcome,
    )
